#include <cstdio>
#include <cstddef>

// 差序：小成员夹在大成员之间，逼出两段填充
struct Before { char a; double b; char c; };
// 好序：按对齐需求从大到小排列，填充被挤掉
struct After  { double b; char a; char c; };

int main() {
    printf("重排前 sizeof=%zu 重排后 sizeof=%zu 省下=%zu 字节\n",
           sizeof(Before), sizeof(After), sizeof(Before) - sizeof(After));
    printf("Before: a=%zu b=%zu c=%zu\n",
           offsetof(Before, a), offsetof(Before, b), offsetof(Before, c));
    printf("After : b=%zu a=%zu c=%zu\n",
           offsetof(After, b), offsetof(After, a), offsetof(After, c));
    printf("重排确实变小: %d\n", (int)(sizeof(After) < sizeof(Before)));
    return 0;
}
